package services

import (
	"crypto/sha256"
	"encoding/binary"
)

// These two functions are generated by ai(Mistral)

func shortUrl(longURL string) string {
	sum := sha256.Sum256([]byte(longURL))
	n := binary.BigEndian.Uint64(sum[:8])
	return base62Encode(n)
}

func base62Encode(n uint64) string {
	if n == 0 {
		return "0"
	}
	out := []byte{}
	for n > 0 {
		out = append([]byte{charset[n%62]}, out...)
		n /= 62
	}
	return string(out)
}
